#include <iostream>
#include <string>
#include <string_view>

enum class ReleaseStage {
    Alpha,
    Beta,
    ReleaseCandidate,
    FinalRelease,
    ContinuousBeta
};

struct SoftwareProduct {
    std::string name;
    int majorVersion;
    int minorVersion;
    ReleaseStage stage;

    std::string_view getStageName() const {
        switch (stage) {
            case ReleaseStage::Alpha:            return "Alpha";
            case ReleaseStage::Beta:             return "Beta";
            case ReleaseStage::ReleaseCandidate: return "Release Candidate";
            case ReleaseStage::FinalRelease:     return "Final Release";
            case ReleaseStage::ContinuousBeta:   return "Continuous Beta";
        }
        return "Unknown";
    }

    bool isFeatureComplete() const {
        return stage == ReleaseStage::ReleaseCandidate ||
               stage == ReleaseStage::FinalRelease ||
               stage == ReleaseStage::ContinuousBeta;
    }
};

int main() {
    SoftwareProduct compilerSuite{"Modern C++ Engine", 2, 0, ReleaseStage::ReleaseCandidate};
    SoftwareProduct cloudEditor{"Web IDE Service", 1, 0, ReleaseStage::ContinuousBeta};

    std::cout << compilerSuite.name << " (v" 
              << compilerSuite.majorVersion << "." << compilerSuite.minorVersion 
              << ") - Stage: " << compilerSuite.getStageName() 
              << " - Feature Complete: " << (compilerSuite.isFeatureComplete() ? "Yes" : "No") 
              << "\n";

    std::cout << cloudEditor.name << " - Stage: " << cloudEditor.getStageName() 
              << " - Feature Complete: " << (cloudEditor.isFeatureComplete() ? "Yes" : "No") 
              << "\n";

    return 0;
}

#include <iostream>
#include <string>

class DeviceController {
private:
    std::string deviceName; // Attribute hidden from external access
    bool activeStatus{false};

public:
    DeviceController(std::string name) : deviceName(std::move(name)) {}

    void activate() {
        activeStatus = true;
        std::cout << "Device [" << deviceName << "] status: ACTIVATED\n";
    }

    void reportHealth() const {
        std::cout << "Device [" << deviceName << "] health: " 
                  << (activeStatus ? "NORMAL" : "INACTIVE") << "\n";
    }

    bool isActive() const {
        return activeStatus;
    }
};

int main() {
    // Standard streams: std::cout represents stdout
    DeviceController sensor{"Accelerometer-X"};
    sensor.activate();
    sensor.reportHealth();
    return 0;
}
